DROP TABLE IF EXISTS T CASCADE;
CREATE TABLE T(c0 INTEGER NOT NULL,c1 INTEGER NOT NULL,c2 INTEGER,c3 INTEGER,c4 INTEGER,c5 INTEGER,c6 INTEGER,c7 INTEGER);
CREATE UNIQUE INDEX k0_0 ON T(c2,c4) WHERE c2 IS NOT NULL AND c4 IS NOT NULL;
CREATE UNIQUE INDEX k0_1 ON T(c4) WHERE c2 IS NULL AND c4 IS NOT NULL;
CREATE UNIQUE INDEX k0_2 ON T(c2) WHERE c4 IS NULL AND c2 IS NOT NULL;
CREATE UNIQUE INDEX k0_3 ON T((1)) WHERE c2 IS NULL AND c4 IS NULL;
CREATE FUNCTION chk_k0() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
  IF (NEW.c2 IS NOT NULL AND NEW.c4 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c4 IS NOT NULL AND c2=NEW.c2 AND c4=NEW.c4) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c4 IS NOT NULL AND c4=NEW.c4) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c4 IS NULL AND c2 IS NOT NULL AND c2=NEW.c2) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c4 IS NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k0 violated'; END IF;
