  IF (NEW.c4 IS NULL AND NEW.c2 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c4 IS NOT NULL AND c2=NEW.c2) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c4 IS NOT NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c4 IS NULL AND c2 IS NOT NULL AND c2=NEW.c2) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c4 IS NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k0 violated'; END IF;
  IF (NEW.c2 IS NULL AND NEW.c4 IS NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c4 IS NOT NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c4 IS NOT NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c4 IS NULL AND c2 IS NOT NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c4 IS NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k0 violated'; END IF;
  RETURN NEW; END $$;
CREATE TRIGGER trg_k0 BEFORE INSERT OR UPDATE ON T FOR EACH ROW EXECUTE FUNCTION chk_k0();
